    const form = document.getElementById('contactForm');
    const fullNameInput = document.getElementById('fullName');
    const emailInput = document.getElementById('email');
    const phoneInput = document.getElementById('phone');
    const successMessage = document.getElementById('successMessage');

    const validateEmail = (email) => {
        return String(email)
            .toLowerCase()
            .match(
                /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
            );
    };

    const validatePhone = (phone) => {
        if (!phone) return true; // Optional
        // Basic format: (XXX) XXX-XXXX
        const phoneRegex = /^\(\d{3}\) \d{3}-\d{4}$/;
        return phoneRegex.test(phone);
    };

    const showError = (input, errorId) => {
        input.classList.add('invalid');
        document.getElementById(errorId).classList.add('visible');
    };

    const hideError = (input, errorId) => {
        input.classList.remove('invalid');
        document.getElementById(errorId).classList.remove('visible');
    };

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        let isValid = true;

        // Name Validation
        if (!fullNameInput.value.trim()) {
            showError(fullNameInput, 'fullNameError');
            isValid = false;
        } else {
            hideError(fullNameInput, 'fullNameError');
        }

        // Email Validation
        if (!validateEmail(emailInput.value)) {
            showError(emailInput, 'emailError');
            isValid = false;
        } else {
            hideError(emailInput, 'emailError');
        }

        // Phone Validation
        if (!validatePhone(phoneInput.value)) {
            showError(phoneInput, 'phoneError');
            isValid = false;
        } else {
            hideError(phoneInput, 'phoneError');
        }

        if (isValid) {
            form.classList.add('hidden');
            successMessage.classList.remove('hidden');
            console.log('Form Submitted:', {
                name: fullNameInput.value,
                email: emailInput.value,
                phone: phoneInput.value
            });
        }
    });

    // Clear errors on input
    [fullNameInput, emailInput, phoneInput].forEach(input => {
        input.addEventListener('input', () => {
            const errorId = input.id + 'Error';
            hideError(input, errorId);
        });
    });
});
